package com.mauri.juryroster;
import android.content.Context;
import android.util.AtomicFile;
import java.io.*;
import java.util.*;
import java.nio.charset.StandardCharsets;
import org.json.*;
public final class Store {
 private final AtomicFile file;
 public Store(Context c){file=new AtomicFile(new File(c.getFilesDir(),"roster.json"));}
 public RosterCore read()throws Exception{if(!file.getBaseFile().exists()&&!new File(file.getBaseFile()+".bak").exists())return new RosterCore();return decode(file.readFully());}
 public void save(RosterCore r)throws Exception{byte[] data=encode(r);FileOutputStream stream=null;try{stream=file.startWrite();stream.write(data);file.finishWrite(stream);}catch(Exception e){if(stream!=null)file.failWrite(stream);throw e;}}
 private static JSONObject map(Map<String,String> m){return new JSONObject(m);}
 private static Map<String,String> map(JSONObject o)throws Exception{Map<String,String> m=new LinkedHashMap<>();Iterator<String> keys=o.keys();while(keys.hasNext()){String k=keys.next();m.put(k,o.getString(k));}return m;}
 private static void set(Set<String> target,JSONArray a)throws Exception{for(int i=0;i<a.length();i++)target.add(a.getString(i));}
 public static byte[] encode(RosterCore r)throws Exception{
  JSONObject o=new JSONObject();o.put("format","JuryRoster");o.put("schema",1);o.put("exportedAt",RosterCore.now());o.put("rosterGroups",new JSONArray(r.rosterGroups));o.put("appName",r.appName);o.put("titles",new JSONArray(Arrays.asList(r.titles)));o.put("countyDomain",r.countyDomain);o.put("countyPattern",r.countyPattern);o.put("term",r.term);o.put("foreperson",r.foreperson);o.put("handoffNotes",r.handoffNotes);o.put("seats",r.seats);o.put("alternateSlots",r.alternateSlots);o.put("importSource",r.importSource);o.put("importedAt",r.importedAt);
  JSONArray ps=new JSONArray();for(RosterCore.Person p:r.people){JSONObject j=new JSONObject();j.put("id",p.id);j.put("titleIds",new JSONArray(p.titleIds));j.put("court",map(p.court));j.put("note",p.note);j.put("emailTest",p.emailTest);j.put("emailTestAt",p.emailTestAt);j.put("createdAt",p.createdAt);j.put("updatedAt",p.updatedAt);j.put("onboarding",new JSONArray(p.onboarding));j.put("lists",new JSONArray(p.lists));j.put("previousEmails",new JSONArray(p.previousEmails));ps.put(j);}o.put("people",ps);
  JSONArray ts=new JSONArray();for(RosterCore.Task t:r.tasks){JSONObject j=new JSONObject();j.put("id",t.id);j.put("personId",t.personId);j.put("list",t.list);j.put("action",t.action);j.put("status",t.status);j.put("oldEmail",t.oldEmail);j.put("newEmail",t.newEmail);j.put("note",t.note);j.put("createdAt",t.createdAt);j.put("completedAt",t.completedAt);ts.put(j);}o.put("tasks",ts);
  JSONArray es=new JSONArray();for(RosterCore.Event e:r.events){JSONObject j=new JSONObject();j.put("at",e.at);j.put("personId",e.personId);j.put("action",e.action);j.put("detail",e.detail);es.put(j);}o.put("events",es);
  JSONArray qs=new JSONArray();for(RosterCore.Proposal q:r.review){JSONObject j=new JSONObject();j.put("id",q.id);j.put("personId",q.personId);j.put("kind",q.kind);j.put("source",q.source);j.put("warning",q.warning);j.put("decision",q.decision);j.put("incoming",map(q.incoming));j.put("before",map(q.before));qs.put(j);}o.put("review",qs);return o.toString(2).getBytes(StandardCharsets.UTF_8);
 }
 public static RosterCore decode(byte[] data)throws Exception{
  if(data.length>8*1024*1024)throw new IOException("Roster file exceeds 8 MB.");JSONObject o=new JSONObject(new String(data,StandardCharsets.UTF_8));if(!o.getString("format").equals("JuryRoster")||o.getInt("schema")!=1)throw new IOException("Unsupported roster format or version.");
  RosterCore r=new RosterCore();if(o.has("rosterGroups")){Set<String> groups=new LinkedHashSet<>();set(groups,o.getJSONArray("rosterGroups"));r.setRosterGroups(groups);}r.appName=o.optString("appName","Civil Grand Jury Roster");if(o.has("titles")){JSONArray titleNames=o.getJSONArray("titles");if(titleNames.length()!=8)throw new IOException("Invalid title configuration.");for(int i=0;i<8;i++)r.titles[i]=titleNames.getString(i); }r.countyDomain=o.optString("countyDomain","amadorcounty.gov");r.countyPattern=o.optString("countyPattern","{first_initial}{last}");r.term=o.getString("term");r.foreperson=o.getString("foreperson");r.handoffNotes=o.getString("handoffNotes");r.seats=o.getInt("seats");r.alternateSlots=o.getInt("alternateSlots");if(r.seats<1||r.seats>100||r.alternateSlots<0||r.alternateSlots>100)throw new IOException("Invalid seat counts.");r.importSource=o.getString("importSource");r.importedAt=o.getString("importedAt");
  Set<String> ids=new HashSet<>();JSONArray ps=o.getJSONArray("people");if(ps.length()>1000)throw new IOException("Too many members.");for(int i=0;i<ps.length();i++){JSONObject j=ps.getJSONObject(i);RosterCore.Person p=new RosterCore.Person();p.id=j.getString("id");if(j.has("titleIds"))set(p.titleIds,j.getJSONArray("titleIds"));if(p.id.isEmpty()||!ids.add(p.id))throw new IOException("Duplicate member IDs.");p.court.putAll(map(j.getJSONObject("court")));p.note=j.getString("note");p.emailTest=j.getString("emailTest");p.emailTestAt=j.getString("emailTestAt");p.createdAt=j.getString("createdAt");p.updatedAt=j.getString("updatedAt");set(p.onboarding,j.getJSONArray("onboarding"));set(p.lists,j.getJSONArray("lists"));set(p.previousEmails,j.getJSONArray("previousEmails"));r.validate(p);r.people.add(p);}
  JSONArray ts=o.getJSONArray("tasks");if(ts.length()>10000)throw new IOException("Too many tasks.");Set<String> taskIds=new HashSet<>();for(int i=0;i<ts.length();i++){JSONObject j=ts.getJSONObject(i);RosterCore.Task t=new RosterCore.Task();t.id=j.getString("id");if(!taskIds.add(t.id))throw new IOException("Duplicate task IDs.");t.personId=j.getString("personId");if(r.find(t.personId)==null)throw new IOException("Task refers to missing member.");t.list=j.getString("list");t.action=j.getString("action");t.status=j.getString("status");if(!Arrays.asList("Add","Remove","Update").contains(t.action)||!Arrays.asList("Pending","Done","Cancelled").contains(t.status))throw new IOException("Invalid list task.");t.oldEmail=j.getString("oldEmail");t.newEmail=j.getString("newEmail");t.note=j.getString("note");t.createdAt=j.getString("createdAt");t.completedAt=j.getString("completedAt");r.tasks.add(t);}
  JSONArray es=o.getJSONArray("events");if(es.length()>30000)throw new IOException("Too many history entries.");for(int i=0;i<es.length();i++){JSONObject j=es.getJSONObject(i);RosterCore.Event e=new RosterCore.Event();e.at=j.getString("at");e.personId=j.getString("personId");e.action=j.getString("action");e.detail=j.getString("detail");r.events.add(e);}
  JSONArray qs=o.getJSONArray("review");if(qs.length()>3000)throw new IOException("Too many import review entries.");for(int i=0;i<qs.length();i++){JSONObject j=qs.getJSONObject(i);RosterCore.Proposal q=new RosterCore.Proposal();q.id=j.getString("id");q.personId=j.getString("personId");q.kind=j.getString("kind");q.source=j.getString("source");q.warning=j.getString("warning");q.decision=j.getString("decision");q.incoming=map(j.getJSONObject("incoming"));q.before=map(j.getJSONObject("before"));r.review.add(q);}return r;
 }
 public static byte[] csv(RosterCore r){
  StringBuilder out=new StringBuilder();List<String> header=new ArrayList<>();header.add("Term");header.add("Record ID");header.add("Juror titles");Collections.addAll(header,RosterCore.LABELS);Collections.addAll(header,"County email test","Test updated","Previous email addresses","Onboarding completed","Confirmed list memberships","Foreperson notes");row(out,header);
  for(RosterCore.Person p:r.people){List<String> values=new ArrayList<>();values.add(r.term);values.add(p.id);values.add(r.titleText(p));for(String f:RosterCore.FIELDS)values.add(p.get(f));Collections.addAll(values,p.emailTest,p.emailTestAt,String.join("; ",p.previousEmails),String.join("; ",p.onboarding),String.join("; ",p.lists),p.note);row(out,values);}return ("\ufeff"+out).getBytes(StandardCharsets.UTF_8);
 }
 private static void row(StringBuilder b,List<String> values){for(int i=0;i<values.size();i++){if(i>0)b.append(',');b.append(CourtFile.csvCell(values.get(i)));}b.append("\r\n");}
}

